/**
 * Concatenate every migration (in order) plus the seed into one SQL file that
 * can be pasted into the Supabase dashboard SQL editor.
 *
 * This is the credential-free fallback when the Management API is unavailable:
 *   node scripts/build-sql-bundle.mjs   ->  dist-sql/full-schema.sql
 */
import { readFileSync, readdirSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const MIGRATIONS_DIR = join(ROOT, 'supabase', 'migrations');
const OUT_DIR = join(ROOT, 'dist-sql');
const OUT_FILE = join(OUT_DIR, 'full-schema.sql');

const files = readdirSync(MIGRATIONS_DIR)
  .filter((f) => f.endsWith('.sql'))
  .sort();

const parts = [
  '-- Driving School SaaS — full schema bundle',
  '-- Generated by scripts/build-sql-bundle.mjs. Apply once to a fresh project.',
  '-- Run inside a transaction where possible; review before executing.',
  '',
  'begin;',
  '',
];

for (const f of files) {
  parts.push(`-- ${'='.repeat(72)}`);
  parts.push(`-- ${f}`);
  parts.push(`-- ${'='.repeat(72)}`);
  parts.push(readFileSync(join(MIGRATIONS_DIR, f), 'utf8').trimEnd());
  parts.push('');
}

parts.push(`-- ${'='.repeat(72)}`);
parts.push('-- seed.sql');
parts.push(`-- ${'='.repeat(72)}`);
parts.push(readFileSync(join(ROOT, 'supabase', 'seed.sql'), 'utf8').trimEnd());
parts.push('');
parts.push('commit;');
parts.push('');

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(OUT_FILE, parts.join('\n'), 'utf8');

console.log(`Wrote ${OUT_FILE} (${files.length} migrations + seed).`);
